INSERT INTO `ai_playerbot_texts` (`name`, `text`, `say_type`, `reply_type`) VALUES
('reply', '你好呀,有什么事吗?', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '在的,找我有什么事?', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '刚才有点忙,没看到消息,你再说一遍?', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '谢谢你的问候,你也多保重!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '需要帮忙打副本吗?我正好有空。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '组队的话算我一个,我输出还可以。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '你说的那件装备,拍卖行有卖的。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '想学什么专业?我教你几个窍门。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '这个任务我做过,跟我走就行。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '稀有怪刚刷新不久,应该还在。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '战场组队?加我一个!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '交易可以,价格好商量。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '稍等,我打完这只怪就回复你。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '抱歉,现在有点忙,回头聊。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '你说的那个坐标,我去看过了,没有东西。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '公会还有位置,欢迎加入我们!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '我对这个也不太懂,帮你问问别人。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '没问题,包在我身上!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '好的,收到!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '哈哈,你这话说得真有意思。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '别客气,朋友之间互相帮助是应该的。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '祝你游戏愉快,好运!', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '下次需要帮忙随时叫我。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '嗯嗯,我知道了。', 0, 0, '', '', '', '', '', '', '', ''),
('reply', '加油,相信你一定能做到!', 0, 0, '', '', '', '', '', '', '', '');
